import "server-only";
import { and, eq } from "drizzle-orm";
import { getDb, schema } from "@/db";
import type { Contact, QuizSubmission } from "@/db/schema";
import { OFFERS, STRATEGY_CALL_HREF, STRATEGY_CALL_SLUG, type Recommendation } from "@/lib/assessment";
import { getActiveMeetingType } from "@/lib/scheduling";
import { formatMoney } from "@/lib/utils";

/** Result tokens are 32 hex chars (generated by the DB default or the submit action). */
export const RESULT_TOKEN_RE = /^[a-zA-Z0-9]{16,64}$/;

export type SubmissionWithContact = {
  submission: QuizSubmission;
  contact: Pick<Contact, "id" | "name" | "email" | "company">;
};

export async function getSubmissionByToken(token: string): Promise<SubmissionWithContact | null> {
  if (!RESULT_TOKEN_RE.test(token)) return null;
  const db = await getDb();
  const [row] = await db
    .select({
      submission: schema.quizSubmissions,
      contact: {
        id: schema.contacts.id,
        name: schema.contacts.name,
        email: schema.contacts.email,
        company: schema.contacts.company,
      },
    })
    .from(schema.quizSubmissions)
    .innerJoin(schema.contacts, eq(schema.contacts.id, schema.quizSubmissions.contactId))
    .where(eq(schema.quizSubmissions.resultToken, token))
    .limit(1);
  return row ?? null;
}

export type OfferDetails = {
  recommendation: Recommendation;
  kind: "course" | "consulting";
  title: string;
  subtitle: string;
  /** Relative URL of the offer page. */
  href: string;
  cta: string;
  priceCents: number | null;
  compareAtCents: number | null;
  coverEmoji: string | null;
  audience: string | null;
  level: string | null;
  durationMin: number | null;
  /** e.g. "$297" or "Free 45-minute call" — used in AI prompts and emails. */
  priceLabel: string | null;
};

/** Loads the live title / price for the recommended offer, falling back to static copy. */
export async function loadOffer(rec: Recommendation): Promise<OfferDetails> {
  const offer = OFFERS[rec];
  const base: OfferDetails = {
    recommendation: rec,
    kind: offer.kind,
    title: offer.name,
    subtitle: offer.blurb,
    href: offer.href,
    cta: offer.cta,
    priceCents: null,
    compareAtCents: null,
    coverEmoji: null,
    audience: null,
    level: null,
    durationMin: null,
    priceLabel: null,
  };
  try {
    if (offer.kind === "course") {
      const db = await getDb();
      const [course] = await db
        .select()
        .from(schema.courses)
        .where(and(eq(schema.courses.slug, offer.slug), eq(schema.courses.published, true)))
        .limit(1);
      // Course unpublished or renamed: send people to the catalog rather than a 404.
      if (!course) return { ...base, href: "/courses", cta: "Browse our courses" };
      return {
        ...base,
        title: course.title,
        subtitle: course.subtitle || offer.blurb,
        href: `/courses/${course.slug}`,
        priceCents: course.priceCents,
        compareAtCents: course.compareAtCents,
        coverEmoji: course.coverEmoji,
        audience: course.audience,
        level: course.level,
        priceLabel: course.priceCents > 0 ? formatMoney(course.priceCents) : "Free",
      };
    }
    const meeting = await getActiveMeetingType(offer.slug);
    if (!meeting) return { ...base, href: "/consulting", cta: "Learn about AI implementation" };
    return {
      ...base,
      subtitle: meeting.description || offer.blurb,
      durationMin: meeting.durationMin,
      priceCents: meeting.priceCents,
      priceLabel: meeting.priceCents > 0 ? formatMoney(meeting.priceCents) : `Free ${meeting.durationMin}-minute discovery call`,
    };
  } catch (err) {
    console.error("[assessment] failed to load offer", rec, err);
    return base;
  }
}

export type StrategyCall = { href: string; durationMin: number | null; free: boolean };

export async function loadStrategyCall(): Promise<StrategyCall> {
  try {
    const meeting = await getActiveMeetingType(STRATEGY_CALL_SLUG);
    if (meeting) return { href: STRATEGY_CALL_HREF, durationMin: meeting.durationMin, free: meeting.priceCents === 0 };
  } catch (err) {
    console.error("[assessment] failed to load strategy call", err);
  }
  return { href: "/book", durationMin: null, free: true };
}

/** Appends ?name=&email= so booking forms open pre-filled (booking pages only). */
export function withPrefill(href: string, person: { name?: string | null; email?: string | null }): string {
  if (!href.startsWith("/book/")) return href;
  const params = new URLSearchParams();
  if (person.name) params.set("name", person.name);
  if (person.email) params.set("email", person.email);
  const qs = params.toString();
  return qs ? `${href}?${qs}` : href;
}
